    els.inspectorCloseBtn?.addEventListener("click", closeInspectorScreen);

    els.addNodeMenuBtn?.addEventListener("click", openAddNodeMenu);
    els.closeAddNodeDialogBtn?.addEventListener("click", () => els.addNodeDialog.close());
