    els.addRandomBtn.addEventListener("click", () => openAddNodeConfig("random"));
    els.addDrillNodeBtn.addEventListener("click", () => openAddNodeConfig("drill"));
    els.addCounterBtn.addEventListener("click", () => openAddNodeConfig("counter"));
